-- Seed Ask's knowledge base: PRD annex F, G3/G4/G5/G7, and the bundled recipes.
-- Idempotent: re-running updates body and source.

on conflict (id) do update set
  topic = excluded.topic,
  title = excluded.title,
  body = excluded.body,
  source = excluded.source,
  source_url = excluded.source_url,
  evidence = excluded.evidence,
  updated_at = now();
