insert into public.knowledge (id, topic, title, body, source, source_url, evidence)
values
  ('f1-lockhart-1957', 'extraction', 'The Brewing Control Chart', 'Lockhart (1957) related soluble solids in the cup to quality and is the origin of the Brewing Control Chart that plots TDS against extraction yield.', 'Lockhart, 1957 — The Soluble Solids in Beverage Coffee as an Index to Cup Quality', 'https://legacy.sca.coffee/research/brewing-control-chart', 'verified'),
  ('f2-guinard-bcc-2023', 'extraction', 'A new Coffee Brewing Control Chart', 'At UC Davis, Guinard, Frost, Batali and colleagues mapped sensory and consumer response across brew strength and extraction. Preference splits into two groups; attributes do not follow the classic chart as a single peak.', 'Guinard et al., J. Food Sci. 2023 — A new Coffee Brewing Control Chart', 'https://pubmed.ncbi.nlm.nih.gov/36789850/', 'verified'),
  ('f3-batali-temperature-2020', 'temperature', 'Brew temperature at fixed strength and extraction', 'At fixed TDS and extraction yield, 87 / 90 / 93 °C change little in the sensory profile of drip coffee. Temperature is a lever to reach extraction, not a taste button.', 'Batali, Ristenpart, Guinard, Sci. Rep. 2020', 'https://pubmed.ncbi.nlm.nih.gov/32733065/', 'verified'),
  ('f4-frost-roast-tds-2020', 'roast', 'Roast level interacts with strength and extraction', 'Roast level changes how brew strength and extraction present in the cup. Darker roasts read heavier at the same TDS.', 'Frost, Ristenpart, Guinard, J. Food Sci. 2020', 'https://pubmed.ncbi.nlm.nih.gov/32572971/', 'verified'),
  ('f5-cotter-preference-2021', 'taste', 'Two preference segments among black-coffee drinkers', 'Consumer tasting across the brewing chart finds two preference segments rather than one ideal zone.', 'Cotter, Batali, Ristenpart, Guinard, J. Food Sci. 2021', 'https://pubmed.ncbi.nlm.nih.gov/33448032/', 'verified'),
  ('f6-cameron-espresso-2020', 'grind', 'Systematically Improving Espresso', 'Too fine a grind can make espresso extraction uneven. Coarser grind and a lower dose often improve reproducibility. Sour and bitter together is an evenness problem, not a level problem.', 'Cameron et al., Matter 2020 — Systematically Improving Espresso', 'https://doi.org/10.1016/j.matt.2019.12.019', 'verified'),
  ('f7-mendez-static-2023', 'grind', 'Moisture-controlled triboelectrification during grinding', 'Bean moisture controls static charge while grinding. A little water (RDT) reduces clumps and can raise espresso extraction.', 'Méndez Harper et al., Matter 2023', 'https://doi.org/10.1016/j.matt.2023.04.007', 'verified'),
  ('f8-mendez-rdt-2023', 'grind', 'Water is the charge-control that changes extraction', 'Of the chemical strategies tried, only water (< 0.05 mL/g) changes extraction parameters. Dark roasts can gain 15 % or more concentration with RDT.', 'Méndez Harper, Hendon et al., arXiv 2312.03103', 'https://arxiv.org/abs/2312.03103', 'verified'),
  ('f9-uman-cold-beans-2016', 'grind', 'Colder beans grind finer and narrower', 'Colder roasted beans produce a finer, narrower particle-size distribution.', 'Uman et al., Sci. Rep. 2016', 'https://www.nature.com/articles/srep24483', 'verified'),
  ('f10-hendon-cations-2014', 'water', 'Dissolved cations in coffee extraction', 'Magnesium and calcium affect extraction of aroma compounds; bicarbonate buffers acidity. Water chemistry is not just TDS.', 'Hendon, Colonna-Dashwood, J. Agric. Food Chem. 2014', 'https://doi.org/10.1021/jf5017124', 'verified'),
  ('f11-scaa-water-2009', 'water', 'SCAA Water for Brewing Specialty Coffee', 'Target ranges for brewing water: TDS about 75–250 ppm, general hardness around 50–175 ppm as CaCO3, alkalinity around 40–75 ppm, pH 6.5–7.5, sodium under 30 ppm.', 'SCAA, Water for Brewing Specialty Coffee, 2009', 'https://sca.coffee/research/coffee-standards', 'verified'),
  ('f12-sca-cva-2024', 'taste', 'SCA Coffee Value Assessment', 'The CVA describes coffee with fragrance, aroma, flavor, aftertaste, acidity, sweetness, mouthfeel and overall. Kohi''s seven taste axes follow this vocabulary.', 'SCA-103 / SCA-104, 2023–2024', 'https://sca.coffee/value-assessment', 'verified'),
  ('f13-flavor-wheel-2016', 'taste', 'Coffee Taster''s Flavor Wheel', 'The SCA / WCR flavor wheel and sensory lexicon (2016) is the shared vocabulary for tasting notes.', 'SCA / WCR Coffee Taster''s Flavor Wheel, 2016', 'https://sca.coffee/research/coffee-tasters-flavor-wheel', 'verified'),
  ('f14-gagne-physics-2020', 'extraction', 'The Physics of Filter Coffee', 'Jonathan Gagné''s Physics of Filter Coffee and Coffee ad Astra cover fines, percolation and water recipes as documented practice, not peer review.', 'Gagné, The Physics of Filter Coffee (2020); Coffee ad Astra', 'https://coffeeadastra.com', 'verified'),
  ('f15-water-for-coffee-2015', 'water', 'Water for Coffee', 'Colonna-Dashwood and Hendon''s Water for Coffee is the reference book on brewing-water chemistry: hardness, alkalinity, and how they taste.', 'Colonna-Dashwood, Hendon — Water for Coffee (2015)', 'https://www.waterforcoffee.com', 'verified'),
  ('f16-moroney-extraction-2015', 'extraction', 'Multiscale extraction modelling', 'Moroney et al. model extraction in a packed bed of coffee, the physics behind why grind, dose and time trade off.', 'Moroney et al., Chem. Eng. Sci. 2015', 'https://doi.org/10.1016/j.ces.2015.06.054', 'verified'),
  ('f17-mo-fines-2021', 'extraction', 'Flow-induced erosion of fines', 'Fines migrate during filtration. Agitation and pour rate change the bed, which is why a stir is a more drastic move than a grind click.', 'Mo, Johnston, Navarini, Ellero, Phys. Fluids 2021', 'https://arxiv.org/abs/2512.21528', 'verified'),
  ('f18-smrke-degas-2018', 'freshness', 'Degassing of roasted coffee', 'Roasted coffee degasses on a curve that depends on roast and grind. That is why a rest window exists, and why a coffee under five days off roast needs a longer bloom.', 'Smrke et al., J. Agric. Food Chem. 2018', 'https://doi.org/10.1021/acs.jafc.7b06051', 'verified'),
  ('f19-coffee-compass', 'diagnosis', 'The Coffee Compass', 'Barista Hustle''s Coffee Compass: sour → finer or longer; bitter → coarser or shorter; weak → shorter ratio; strong and muddy → longer ratio. One variable at a time.', 'Barista Hustle — DIY Water Recipes Redux; The Coffee Compass', 'https://www.baristahustle.com/blog/the-coffee-compass/', 'verified'),
  ('g3-temperature', 'temperature', 'Starting temperature by roast (G3)', 'Filter: light 94–100 °C, medium 90–94 °C, dark 85–90 °C. Espresso a few degrees cooler. Decaf: −2 °C and one notch coarser. Temperature mainly reaches extraction (F3).', 'Kohi G3; F3 Batali 2020', null, 'verified'),
  ('g4-strength', 'extraction', 'TDS and extraction yield (G4)', 'Filter usually sits around 1.15–1.45 % TDS and 18–22 % extraction. Espresso 8–12 % TDS, same yield band. EY = TDS × beverage ÷ dose. What TDS and extraction yield mean is this arithmetic, not a taste score.', 'Kohi G4; SCAA Brewing Control Chart', null, 'verified'),
  ('g7-diagnosis', 'diagnosis', 'Suggested correction rules (G7)', 'Sour and not bitter, short time: grind finer (under-extracted). Bitter and long: grind coarser. Thin body, axes otherwise fine: shorter ratio (more strength, same extraction). Sour and bitter together: do not move the grind; check water and distribution. Yield over 22 % with bitterness: shorter time or cooler water. A V60 that tastes sour is usually under-extracted: finer grind or hotter water, not more acidity.', 'Kohi G7; Coffee Compass; F6', null, 'verified'),
  ('g5-rest', 'freshness', 'Rest after roasting (G5)', 'Filter, light roast: commonly 7–21 days off roast. Espresso 10–30 days. Darker roasts degas faster. Freezing extends the window. A coffee needs to rest so CO2 stops blowing the bed apart.', 'Kohi G5', null, 'verified'),
  ('recipe-a1-v60-ultimate', 'recipe', 'V60 « Ultimate »', 'V60 « Ultimate » by James Hoffmann (2019). Dose 30 g. Water 500 g. 99 °C. Grind medium-fine. About 210 s. Steps: 0s bloom to 60g; 45s pour to 300g; 75s pour to 500g; 105s stir; 120s drawdown. Just off the boil for light roasts; 93–95 °C for anything darker.', 'James Hoffmann (2019)', 'https://www.youtube.com/watch?v=1oB1oDrDkHM', 'verified'),
  ('recipe-a2-v60-one-cup', 'recipe', 'V60 « 1 cup »', 'V60 « 1 cup » by James Hoffmann (2022). Dose 15 g. Water 250 g. 100 °C. Grind medium-fine. About 180 s. Steps: 0s bloom to 50g; 45s pour to 150g; 60s pour to 175g; 70s pour to 200g; 80s pour to 225g; 90s pour to 250g; 100s swirl. Dose, water and total time check out; the pour breakdown still needs the source.', 'James Hoffmann (2022)', 'https://www.youtube.com/watch?v=1oB1oDrDkHM', 'verified'),
  ('recipe-a3-v60-46', 'recipe', 'V60 « 4:6 »', 'V60 « 4:6 » by Tetsu Kasuya (WBrC 2016). Dose 20 g. Water 300 g. 92 °C. Grind coarse. About 210 s. Steps: 0s pour to 60g; 45s pour to 120g; 90s pour to 180g; 135s pour to 240g; 180s pour to 300g. First two pours (40 %) set sweetness against acidity; the last three (60 %) set strength — three pours is balanced, two is stronger, one is lighter. The principle is verified; the temperature and the direction of the adjustments are not.', 'Tetsu Kasuya (WBrC 2016)', 'https://www.youtube.com/watch?v=wmCPQZWFXsQ', 'verified'),
  ('recipe-a5-kalita-wave', 'recipe', 'Kalita Wave 185', 'Kalita Wave 185 by common practice. Dose 20 g. Water 320 g. 93 °C. Grind medium. About 195 s. Steps: 0s bloom to 50g; 30s pour to 140g; 75s pour to 230g; 120s pour to 320g. Flat bottom, so the bed stays level and the pours can be blunt.', 'common practice', null, 'verified'),
  ('recipe-a6-chemex-six', 'recipe', 'Chemex 6 cup', 'Chemex 6 cup by common practice. Dose 40 g. Water 640 g. 94 °C. Grind medium-coarse. About 285 s. Steps: 0s bloom to 100g; 45s pour to 400g; 105s pour to 640g; 180s drawdown. The thick filter is slow: expect four and a half to five minutes.', 'common practice', null, 'verified'),
  ('recipe-a7-aeropress-ultimate', 'recipe', 'AeroPress « Ultimate »', 'AeroPress « Ultimate » by James Hoffmann (2023). Dose 11 g. Water 200 g. 100 °C. Grind fine-medium. About 180 s. Steps: 0s pour to 200g; 120s swirl; 150s press. Upright, no bloom, no agitation. 100 °C for light roasts, 85–90 °C for dark. The outline is verified; the temperatures are not.', 'James Hoffmann (2023)', 'https://www.youtube.com/watch?v=j6VlT_jUVPc', 'verified'),
  ('recipe-a8-aeropress-inverted', 'recipe', 'AeroPress inverted', 'AeroPress inverted by common practice. Dose 14 g. Water 200 g. 90 °C. Grind medium-fine. About 120 s. Steps: 0s pour to 200g; 10s stir; 90s press. ', 'common practice', null, 'verified'),
  ('recipe-a9-espresso-standard', 'recipe', 'Espresso, standard', 'Espresso, standard by convention (Barista Hustle, Hoffmann). Dose 18 g. Beverage 36 g. 92 °C. Grind fine. About 27 s. Set the grind by time first, then by taste: sour means finer or longer, bitter means coarser or shorter. About 9 bar.', 'convention (Barista Hustle, Hoffmann)', null, 'verified'),
  ('recipe-a10-espresso-turbo', 'recipe', 'Espresso, light / « turbo »', 'Espresso, light / « turbo » by practice (Rao, Barista Hustle). Dose 18 g. Beverage 50 g. 94 °C. Grind medium-fine. About 20 s. Coarser than the standard shot, 1:2.5 to 1:3, 6 bar if the machine allows it. Same tuning logic.', 'practice (Rao, Barista Hustle)', null, 'verified'),
  ('recipe-a11-moka', 'recipe', 'Moka, 3 cup', 'Moka, 3 cup by James Hoffmann. Dose 16 g. 100 °C. Grind fine (moka). Steps: 0s steep; 1s release. Basket level and untamped, preheated water to just under the valve, medium-low heat with the lid open. Off the heat at the first gurgle, then cool the base under the tap. The method is verified; the dose is not.', 'James Hoffmann', 'https://www.youtube.com/watch?v=BeALTCUbYQg', 'verified'),
  ('recipe-a12-french-press', 'recipe', 'French press', 'French press by James Hoffmann. Dose 30 g. Water 500 g. 99 °C. Grind medium-coarse. About 600 s. Steps: 0s pour to 500g; 240s stir; 300s steep; 600s release. Pour without plunging: the plunger is a lid, not a filter.', 'James Hoffmann', 'https://www.youtube.com/watch?v=st571DYYTR8', 'verified'),
  ('recipe-a13-clever-dripper', 'recipe', 'Clever Dripper', 'Clever Dripper by common practice. Dose 20 g. Water 320 g. 93 °C. Grind medium. About 240 s. Steps: 0s pour to 320g; 120s stir; 150s release. ', 'common practice', null, 'verified'),
  ('recipe-a14-cold-brew', 'recipe', 'Cold brew concentrate', 'Cold brew concentrate by common practice. Dose 60 g. Water 480 g. 20 °C. Grind coarse. About 50400 s. Steps: 0s pour to 480g; 50400s release. 12 to 16 hours at room temperature, or 16 to 24 in the fridge. Filter, then dilute about 1:1.', 'common practice', null, 'verified'),
  ('recipe-a15-cupping-sca', 'recipe', 'Cupping, SCA protocol', 'Cupping, SCA protocol by SCA cupping protocol. Dose 8.25 g. Water 150 g. 93 °C. Grind medium-coarse. About 600 s. Steps: 0s pour to 150g; 240s stir; 600s steep. 1:18.2 by definition. Taste as it cools, from about ten minutes. The historic protocol; the 2024 CVA revision still needs checking.', 'SCA cupping protocol', 'https://sca.coffee/research/protocols-best-practices', 'verified'),
  ('recipe-a16-batch-drip', 'recipe', 'Batch drip', 'Batch drip by SCA Golden Cup (55 g/L ± 10 %). Dose 60 g. Water 1000 g. 94 °C. Grind medium. Steps: 0s bloom to 120g; 30s pour to 1000g. 55 to 60 g per litre. Bloom by hand for 30 s if the machine lets you. The ratio is verified; the temperature is not.', 'SCA Golden Cup (55 g/L ± 10 %)', 'https://sca.coffee/research/protocols-best-practices', 'verified')
